import json

# Input data is provided by the harness as a dictionary named `input_data`
map_id = input_data.get('map_id')
start_x = int(input_data.get('start_x'))
start_y = int(input_data.get('start_y'))
start_z = int(input_data.get('start_z'))
target_x = int(input_data.get('target_x'))
target_y = int(input_data.get('target_y'))
target_z = int(input_data.get('target_z'))

def is_plateau_tile(x, y):
    if map_id == '0_219':
        # Western plateau: Columns 5-11, Rows 16-18
        if (5 <= x <= 11) and (16 <= y <= 18):
            return True
        # Eastern plateau central part: Columns 11-16, Rows 6-18
        if (11 <= x <= 16) and (6 <= y <= 18):
            # Columns 11-14 on Rows 13-15 are ground level (valley), not plateau!
            if (11 <= x <= 14) and (13 <= y <= 15):
                return False
            return True
        # Eastern plateau eastern extension: Columns 17-22, Rows 14-16 (Row 13 is ground level!)
        if (17 <= x <= 22) and (14 <= y <= 16):
            return True
    return False

def get_neighbors(cx, cy, cz):
    neighbors = []
    # (dx, dy, button)
    moves = [(0, 1, 'Down'), (0, -1, 'Up'), (-1, 0, 'Left'), (1, 0, 'Right')]

    # Map 0_219 (West) Specific Rules and Transitions
    if map_id == '0_219':
        # 1. Stairs and ramps transitions (3D transitions)
        # Eastern stairs UP: Z=0 at (21,18) -> (21,17) -> Z=1 at (21,16)
        if cz == 0 and cx == 21 and cy == 18:
            neighbors.append((21, 17, 0, 'Up'))
        elif cz == 0 and cx == 21 and cy == 17:
            neighbors.append((21, 16, 1, 'Up'))
            neighbors.append((21, 18, 0, 'Down'))
        elif cz == 1 and cx == 21 and cy == 16:
            neighbors.append((21, 17, 0, 'Down'))

        # Western stairs DOWN: Z=1 at (6,18) -> (6,19) -> Z=0 at (6,20)
        elif cz == 1 and cx == 6 and cy == 18:
            neighbors.append((6, 19, 1, 'Down'))
        elif cz == 1 and cx == 6 and cy == 19:
            neighbors.append((6, 20, 0, 'Down'))
            neighbors.append((6, 18, 1, 'Up'))
        elif cz == 0 and cx == 6 and cy == 20:
            neighbors.append((6, 19, 1, 'Up'))

        # Plateau ramp transition: (18, 9, 1) <-> (19, 9, 0)
        elif cz == 1 and cx == 18 and cy == 9:
            neighbors.append((19, 9, 0, 'Right'))
        elif cz == 0 and cx == 19 and cy == 9:
            neighbors.append((18, 9, 1, 'Left'))

        # 2. Standard 2D moves on same Z
        for dx, dy, btn in moves:
            nx, ny = cx + dx, cy + dy
            if nx < 0 or nx >= 30 or ny < 0 or ny >= 24:
                continue

            if cz == 0:
                # Ground obstacles: cannot step on plateau
                if is_plateau_tile(nx, ny):
                    continue
                if nx == 24: # Column 24 trees
                    continue
                if ny == 13 and nx <= 14: # Row 13 water / trees
                    continue
                if nx == 9 and 10 <= ny <= 13: # Column 9 water
                    continue
                if nx == 10 and ny == 11: # Rest House wall
                    continue
                if nx == 14 and 12 <= ny <= 15: # Plateau wall
                    continue
                # Row 17 cliff edge is impassable on ground (under stairs/plateau)
                if ny == 17 and 17 <= nx <= 23:
                    continue
                # Column 23 cliff wall is impassable on ground
                if nx == 23 and 14 <= ny <= 17:
                    continue
                neighbors.append((nx, ny, 0, btn))

            elif cz == 1:
                # Plateau boundary Constraints
                if not is_plateau_tile(nx, ny):
                    continue
                if ny == 5 and 11 <= nx <= 16:
                    continue
                # Specific checked wall on plateau: (18,17) is blocked
                if nx == 18 and ny == 17:
                    continue
                # Column 17 is solid cliff face across Rows 6-13, and cannot be crossed on plateau
                if nx == 17 and 6 <= ny <= 13:
                    continue
                neighbors.append((nx, ny, 1, btn))

    # Standard 2D navigation for other maps (Center, East, North)
    else:
        for dx, dy, btn in moves:
            nx, ny = cx + dx, cy + dy
            # Simple bounds check
            if nx < 0 or nx >= 40 or ny < 0 or ny >= 40:
                continue
            neighbors.append((nx, ny, cz, btn))

    return neighbors

# BFS Algorithm to find shortest path
queue = [[(start_x, start_y, start_z), []]]
visited = set([(start_x, start_y, start_z)])
path = None

while queue:
    curr, btns = queue.pop(0)
    if curr == (target_x, target_y, target_z):
        path = btns
        break
    for nx, ny, nz, btn in get_neighbors(*curr):
        if (nx, ny, nz) not in visited:
            visited.add((nx, ny, nz))
            queue.append(((nx, ny, nz), btns + [btn]))

if path is not None:
    print(json.dumps(path))
else:
    print(json.dumps([]))
